import os
def find_recursive(base, name, max_depth=5):
    """Find files matching name within max_depth"""
    for root, dirs, files in os.walk(base, followlinks=False):
        if root.count('/') > base.count('/') + max_depth:
            del dirs[:]
        for f in files:
